import{_ as o,H as a,f as r,i as t}from"./chunks/framework.BauLNg70.js";const p=JSON.parse('{"title":"Mods destacados","description":"","frontmatter":{},"headers":[],"relativePath":"featured.md","filePath":"featured.md"}'),s={name:"featured.md"};function i(n,e,d,l,c,u){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="mods-destacados" tabindex="-1">Mods destacados <a class="header-anchor" href="#mods-destacados" aria-label="Permalink to &quot;Mods destacados&quot;">​</a></h1><p>Selección curada por el estudio. Sin algoritmos: una persona del equipo elige y la lista vive en <a href="https://github.com/leteoworks/mod-portal-snake-classic/blob/main/featured.json" target="_blank" rel="noreferrer"><code>featured.json</code></a> del repo del portal. Las elecciones se documentan en <a href="https://github.com/leteoworks/my-game-fw/blob/main/docs/mods/operations/featured-mods-curation.md" target="_blank" rel="noreferrer"><code>operations/featured-mods-curation.md</code></a> del repo del framework.</p><blockquote><p><strong>No es un sistema de partnership ni pago</strong>. Aparecer aquí no implica acuerdo comercial — es reconocimiento gratuito al trabajo del modder. Si el verification tier (<code>workshopVerified</code>) se activa en el futuro, los mods featured podrán pasar al tier verified con proceso aparte.</p></blockquote><hr><h2 id="mod-del-mes" tabindex="-1">Mod del mes <a class="header-anchor" href="#mod-del-mes" aria-label="Permalink to &quot;Mod del mes&quot;">​</a></h2><p><em>Sin nominado para este mes. ¿Conoces un mod que merezca destacarse? Ábrelo en <a href="https://steamcommunity.com/app/TBD/workshop/" target="_blank" rel="noreferrer">Workshop Discussions</a> con el tag &quot;Featured nomination&quot;.</em></p><hr><h2 id="seleccion-actual" tabindex="-1">Selección actual <a class="header-anchor" href="#seleccion-actual" aria-label="Permalink to &quot;Selección actual&quot;">​</a></h2><h3 id="fun-config-—-by-studio-leteo" tabindex="-1">Fun Config — by Studio Leteo <a class="header-anchor" href="#fun-config-—-by-studio-leteo" aria-label="Permalink to &quot;Fun Config — by Studio Leteo&quot;">​</a></h3><p><code>studio.fun-config</code> · <em>First Party · Customization</em></p><p>Mod oficial first-party. Personaliza power-ups, velocidad y progresión con presets divertidos. Sirve de referencia viva para modders que estén empezando — su código está en <a href="https://github.com/leteoworks/my-game-fw/tree/main/src/games/snake-classic/mods/bundled/studio.fun-config" target="_blank" rel="noreferrer"><code>src/games/snake-classic/mods/bundled/studio.fun-config/</code></a> del repo del framework, abierto y clonable.</p><hr><h2 id="¿como-nominar-un-mod" tabindex="-1">¿Cómo nominar un mod? <a class="header-anchor" href="#¿como-nominar-un-mod" aria-label="Permalink to &quot;¿Cómo nominar un mod?&quot;">​</a></h2><ol><li>El mod tiene que estar publicado en Steam Workshop con visibility Public.</li><li>Abre un thread en Workshop Discussions del juego con título <code>Featured nomination: &lt;modId&gt;</code>.</li><li>Incluye 2-3 frases de por qué el mod merece destacarse.</li><li>El estudio revisa periódicamente las nominaciones (no es instantáneo — esperamos que pasen días/semanas).</li><li>Si entra, aparece aquí + en la home del portal. El modder recibe ping en Workshop Discussions.</li></ol><h2 id="¿como-se-quita" tabindex="-1">¿Cómo se quita? <a class="header-anchor" href="#¿como-se-quita" aria-label="Permalink to &quot;¿Cómo se quita?&quot;">​</a></h2><p>Auto: la curación es <strong>reset cada 6 meses</strong> para evitar que los mods featured se queden indefinidamente. Mods muy duraderos (e.g. Fun Config) re-aparecen tras revisión.</p><p>Reactivo: si el estudio detecta que un mod featured se ha vuelto problemático (bugs persistentes, autor abandonó, comportamiento malicioso descubierto), sale inmediatamente del featured. Caso extremo → kill-switch operacional (ver <a href="https://github.com/leteoworks/my-game-fw/blob/main/docs/mods/operations/kill-switch-runbook.md" target="_blank" rel="noreferrer"><code>kill-switch-runbook.md</code></a>).</p>',17)])])}const f=o(s,[["render",i]]);export{p as __pageData,f as default};
